export async function mapLimit(items, limit, worker) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an Array');
  }

  if (!Number.isSafeInteger(limit) || limit <= 0) {
    throw new TypeError('limit must be a positive safe integer');
  }

  if (typeof worker !== 'function') {
    throw new TypeError('worker must be a function');
  }

  if (items.length === 0) {
    return [];
  }

  const snapshot = items.slice();
  const results = new Array(snapshot.length);
  let nextIndex = 0;
  let activeWorkers = 0;
  let firstFailure = null;
  let hasFailure = false;
  let promiseSettled = false;

  return new Promise((resolve, reject) => {
    function settle() {
      if (activeWorkers === 0 && !promiseSettled) {
        promiseSettled = true;
        if (hasFailure) {
          reject(firstFailure);
        } else {
          resolve(results);
        }
      }
    }

    function startWorker() {
      if (nextIndex >= snapshot.length || hasFailure) {
        return;
      }

      const index = nextIndex;
      const value = snapshot[index];
      nextIndex++;
      activeWorkers++;

      let result;
      try {
        result = worker(value, index);
      } catch (err) {
        activeWorkers--;

        if (!hasFailure) {
          hasFailure = true;
          firstFailure = err;
        }

        settle();
        return;
      }

      Promise.resolve(result).then(
        (res) => {
          results[index] = res;
          activeWorkers--;

          if (!hasFailure) {
            startWorker();
          }

          settle();
        },
        (err) => {
          activeWorkers--;

          if (!hasFailure) {
            hasFailure = true;
            firstFailure = err;
          }

          settle();
        }
      );
    }

    const initialWorkers = Math.min(limit, snapshot.length);
    for (let i = 0; i < initialWorkers; i++) {
      startWorker();
      if (hasFailure) {
        break;
      }
    }

    settle();
  });
}
