export async function mapLimit(items, limit, worker) {
  // Validate arguments before admitting any work
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an Array');
  }
  if (!Number.isSafeInteger(limit) || limit <= 0) {
    throw new TypeError('limit must be a positive safe integer');
  }
  if (typeof worker !== 'function') {
    throw new TypeError('worker must be a function');
  }

  // Handle empty input
  if (items.length === 0) {
    return [];
  }

  // Snapshot array values
  const snapshot = Array.from(items);
  const n = snapshot.length;
  const results = new Array(n);

  // Lifecycle state
  let failure = null;
  let hasFailure = false;

  // Obligations tracking
  let admitted = 0;
  let settled = 0;
  let pendingCount = 0;

  return new Promise((resolve, reject) => {
    function checkCompletion() {
      if (admitted === settled) {
        if (hasFailure) {
          reject(failure);
        } else {
          resolve(results);
        }
      }
    }

    function admit() {
      // Admit workers up to the limit, stop if we've seen a failure
      while (pendingCount < limit && admitted < n && !hasFailure) {
        const index = admitted;
        admitted++;

        // Invoke worker and handle both sync throws and async promises
        let workerPromise;
        try {
          const result = worker(snapshot[index], index);
          workerPromise = Promise.resolve(result);
        } catch (error) {
          // Wrap synchronous throw in a rejected promise
          workerPromise = Promise.reject(error);
          hasFailure = true;
          failure = error;
        }

        // Track the obligation
        pendingCount++;

        // Attach handlers to normalize completion
        workerPromise.then(
          (value) => {
            results[index] = value;
            pendingCount--;
            settled++;

            // Try to fill the slot if no failure yet
            if (!hasFailure) {
              admit();
            }

            checkCompletion();
          },
          (error) => {
            pendingCount--;
            settled++;

            // Record first failure only
            if (!hasFailure) {
              hasFailure = true;
              failure = error;
            }

            checkCompletion();
          }
        );

        // Stop admitting if we caught a synchronous error
        if (hasFailure) {
          break;
        }
      }

      // Check if we've finished all work
      checkCompletion();
    }

    // Bootstrap the process
    admit();
  });
}
