export async function retry(operation, options) {
  // Validate arguments
  if (typeof operation !== 'function') {
    throw new TypeError('operation must be a function');
  }
  if (options === null || typeof options !== 'object') {
    throw new TypeError('options must be a non-null object');
  }
  if (!Number.isSafeInteger(options.maxAttempts) || options.maxAttempts <= 0) {
    throw new TypeError('options.maxAttempts must be a positive safe integer');
  }
  if (typeof options.shouldRetry !== 'function') {
    throw new TypeError('options.shouldRetry must be a function');
  }
  if (typeof options.wait !== 'function') {
    throw new TypeError('options.wait must be a function');
  }

  for (let attempt = 1; attempt <= options.maxAttempts; attempt++) {
    try {
      const result = await operation(attempt);
      return result;
    } catch (failure) {
      // Operation failed
      if (attempt === options.maxAttempts) {
        throw failure;
      }

      // Call shouldRetry policy
      let shouldRetryResult;
      try {
        shouldRetryResult = options.shouldRetry(failure, attempt);
      } catch (policyError) {
        throw policyError;
      }

      // Check if it's a thenable and await it
      if (shouldRetryResult && typeof shouldRetryResult.then === 'function') {
        try {
          shouldRetryResult = await shouldRetryResult;
        } catch (thenableError) {
          throw thenableError;
        }
      }

      // Check if result is boolean
      if (typeof shouldRetryResult !== 'boolean') {
        throw new TypeError('shouldRetry must return a boolean');
      }

      // If shouldn't retry, reject
      if (!shouldRetryResult) {
        throw failure;
      }

      // Call wait hook
      await options.wait(attempt);
    }
  }
}
