export function createLedger(initialAccounts) {
  if (!Array.isArray(initialAccounts)) {
    throw new Error('initialAccounts must be an array');
  }

  const accounts = [];
  const idSet = new Set();

  for (const account of initialAccounts) {
    if (!account || typeof account !== 'object' || Array.isArray(account)) {
      throw new Error('Each account must be an object');
    }

    const id = account.id;
    const balance = account.balance;

    if (typeof id !== 'string') {
      throw new Error('Account id must be a string');
    }

    if (!Number.isSafeInteger(balance) || balance < 0) {
      throw new Error('Account balance must be a nonnegative safe integer');
    }

    if (idSet.has(id)) {
      throw new Error('Duplicate account id');
    }

    idSet.add(id);
    accounts.push({ id, balance });
  }

  const accountMap = new Map(accounts.map(acc => [acc.id, { ...acc }]));
  const initialOrder = accounts.map(acc => acc.id);

  function snapshot() {
    const result = [];
    for (const id of initialOrder) {
      const account = accountMap.get(id);
      result.push({ id: account.id, balance: account.balance });
    }
    return result;
  }

  function apply(batch) {
    if (!Array.isArray(batch)) {
      throw new Error('batch must be an array');
    }

    for (const transfer of batch) {
      if (!transfer || typeof transfer !== 'object' || Array.isArray(transfer)) {
        throw new Error('Each transfer must be an object');
      }

      const { from, to, amount } = transfer;

      if (typeof from !== 'string' || !accountMap.has(from)) {
        throw new Error('Transfer from account does not exist');
      }

      if (typeof to !== 'string' || !accountMap.has(to)) {
        throw new Error('Transfer to account does not exist');
      }

      if (!Number.isSafeInteger(amount) || amount <= 0) {
        throw new Error('Transfer amount must be a positive safe integer');
      }
    }

    const workingCopy = new Map(
      Array.from(accountMap.entries()).map(([id, acc]) => [id, { ...acc }])
    );

    for (const transfer of batch) {
      const { from, to, amount } = transfer;

      const fromAcc = workingCopy.get(from);
      const toAcc = workingCopy.get(to);

      if (fromAcc.balance < amount) {
        throw new Error('Insufficient funds');
      }

      fromAcc.balance -= amount;
      toAcc.balance += amount;

      if (fromAcc.balance < 0 || toAcc.balance > Number.MAX_SAFE_INTEGER) {
        throw new Error('Balance constraint violated');
      }
    }

    for (const [id, acc] of workingCopy) {
      accountMap.set(id, { ...acc });
    }

    return snapshot();
  }

  return { snapshot, apply };
}
