export async function retry(operation, options) {
  // Validate options
  if (options === null || typeof options !== 'object') {
    throw new TypeError('options must be a non-null object');
  }

  // Validate operation
  if (typeof operation !== 'function') {
    throw new TypeError('operation must be a function');
  }

  // Extract and validate options properties
  const { maxAttempts, shouldRetry, wait } = options;

  if (!Number.isSafeInteger(maxAttempts) || maxAttempts <= 0) {
    throw new TypeError('maxAttempts must be a positive safe integer');
  }

  if (typeof shouldRetry !== 'function') {
    throw new TypeError('shouldRetry must be a function');
  }

  if (typeof wait !== 'function') {
    throw new TypeError('wait must be a function');
  }

  // Main retry loop
  let attempt = 1;
  while (true) {
    try {
      // Call operation with current attempt number
      const result = await Promise.resolve(operation(attempt));
      return result;
    } catch (failure) {
      // If max attempts reached, reject with the failure
      if (attempt === maxAttempts) {
        throw failure;
      }

      // Call shouldRetry policy
      let shouldRetryResult;
      try {
        shouldRetryResult = shouldRetry(failure, attempt);
      } catch (policyError) {
        throw policyError;
      }

      // Observe rejection from thenable to prevent unhandled promise rejection
      if (
        shouldRetryResult !== null &&
        typeof shouldRetryResult === 'object' &&
        typeof shouldRetryResult.then === 'function'
      ) {
        try {
          await shouldRetryResult;
        } catch (e) {
          // Rejection observed
        }
        throw new TypeError('shouldRetry must return a boolean');
      }

      // Validate return value is boolean
      if (typeof shouldRetryResult !== 'boolean') {
        throw new TypeError('shouldRetry must return a boolean');
      }

      // If policy says don't retry, reject with operation failure
      if (!shouldRetryResult) {
        throw failure;
      }

      // Call wait hook before next attempt
      try {
        await Promise.resolve(wait(attempt));
      } catch (waitError) {
        throw waitError;
      }

      // Proceed to next attempt
      attempt += 1;
    }
  }
}
