export async function mapLimit(items, limit, worker) {
  // Validation
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an Array');
  }

  if (!Number.isSafeInteger(limit) || limit <= 0) {
    throw new TypeError('limit must be a positive safe integer');
  }

  if (typeof worker !== 'function') {
    throw new TypeError('worker must be a function');
  }

  // Snapshot array
  const snapshot = Array.from(items);

  const results = new Array(snapshot.length);
  let activeWorkers = 0;
  let nextIndex = 0;
  let firstError = undefined;
  let errorOccurred = false;

  const pendingPromises = [];

  // Helper to start a worker
  function startWorker(index) {
    activeWorkers++;
    const value = snapshot[index];

    let result;
    try {
      result = worker(value, index);
    } catch (err) {
      // Synchronous throw - record error and stop admitting
      if (!errorOccurred) {
        errorOccurred = true;
        firstError = err;
      }
      activeWorkers--;
      return;
    }

    const workerPromise = Promise.resolve(result);

    const resultPromise = workerPromise.then(
      (resolvedResult) => {
        results[index] = resolvedResult;
        activeWorkers--;

        // If no error yet and more work, admit next
        if (!errorOccurred && nextIndex < snapshot.length) {
          startWorker(nextIndex++);
        }
      },
      (err) => {
        activeWorkers--;

        // Record first error
        if (!errorOccurred) {
          errorOccurred = true;
          firstError = err;
        }

        // Don't rethrow - we handle the error later
      }
    );

    pendingPromises.push(resultPromise);
  }

  // Start initial workers
  const initialCount = Math.min(limit, snapshot.length);
  for (let i = 0; i < initialCount; i++) {
    startWorker(nextIndex++);
    if (errorOccurred) break; // Stop if synchronous error
  }

  // Wait for all admitted workers to settle
  await Promise.all(pendingPromises);

  // If error occurred, reject with it
  if (errorOccurred) {
    throw firstError;
  }

  return results;
}
