export async function mapLimit(items, limit, worker) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an Array');
  }
  if (!Number.isSafeInteger(limit) || limit < 1) {
    throw new TypeError('limit must be a positive safe integer');
  }
  if (typeof worker !== 'function') {
    throw new TypeError('worker must be a function');
  }

  const snapshot = Array.from(items);
  if (snapshot.length === 0) {
    return [];
  }

  const results = new Array(snapshot.length);
  const inFlight = new Map();
  let nextIndex = 0;
  let firstFailure = null;
  let hasFailure = false;

  function admit() {
    if (hasFailure || nextIndex >= snapshot.length) {
      return;
    }
    const index = nextIndex++;
    let promise;
    try {
      promise = Promise.resolve(worker(snapshot[index], index));
    } catch (error) {
      hasFailure = true;
      firstFailure = error;
      promise = Promise.reject(error);
    }

    const wrappedPromise = promise
      .then(result => {
        results[index] = result;
        inFlight.delete(index);
        admit();
      })
      .catch(error => {
        if (!hasFailure) {
          hasFailure = true;
          firstFailure = error;
        }
        inFlight.delete(index);
        admit();
      });

    inFlight.set(index, wrappedPromise);
  }

  for (let i = 0; i < Math.min(limit, snapshot.length); i++) {
    admit();
  }

  while (inFlight.size > 0) {
    await Promise.race(Array.from(inFlight.values()));
  }

  if (hasFailure) {
    throw firstFailure;
  }

  return results;
