export async function mapLimit(items, limit, worker) {
  // Validate arguments before any worker invocation
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an Array');
  }
  if (!Number.isSafeInteger(limit) || limit <= 0) {
    throw new TypeError('limit must be a positive safe integer');
  }
  if (typeof worker !== 'function') {
    throw new TypeError('worker must be a function');
  }

  // Snapshot the array's values
  const snapshot = items.slice();

  // Empty valid input resolves to empty array
  if (snapshot.length === 0) {
    return [];
  }

  // Storage for results in input order
  const results = new Array(snapshot.length);

  // Admission and completion tracking
  let nextIndex = 0;
  let inFlight = 0;
  let firstFailure = null;
  let hasFailure = false;

  return new Promise((resolve, reject) => {
    // Handle successful worker completion
    const onWorkerSuccess = (index, result) => {
      results[index] = result;
      inFlight--;

      // Refill slots if no failure yet
      if (!hasFailure) {
        tryAdmitMore();
      }

      // Check if all work is done
      tryResolve();
    };

    // Handle worker failure
    const onWorkerFailure = (error) => {
      // Record first failure
      if (!hasFailure) {
        hasFailure = true;
        firstFailure = error;
      }

      inFlight--;
      tryResolve();
    };

    // Admit workers up to the limit
    const tryAdmitMore = () => {
      while (inFlight < limit && nextIndex < snapshot.length && !hasFailure) {
        const index = nextIndex++;
        const value = snapshot[index];
        inFlight++;

        // Invoke worker and handle sync throws and async results
        let promise;
        try {
          promise = Promise.resolve(worker(value, index));
        } catch (error) {
          // Synchronous throw observed immediately
          if (!hasFailure) {
            hasFailure = true;
            firstFailure = error;
          }
          inFlight--;
          break;
        }

        promise.then(
          (result) => onWorkerSuccess(index, result),
          (error) => onWorkerFailure(error)
        );
      }
    };

    // Resolve or reject when all obligations are settled
    const tryResolve = () => {
      if (inFlight === 0) {
        if (hasFailure) {
          reject(firstFailure);
        } else if (nextIndex >= snapshot.length) {
          resolve(results);
        }
      }
    };

    // Start initial batch of workers
    tryAdmitMore();
  });
