export function createLedger(initialAccounts) {
  // Validate and store initial accounts
  if (!Array.isArray(initialAccounts)) {
    throw new Error('initialAccounts must be an array');
  }

  const accounts = new Map();
  const accountOrder = [];

  for (let i = 0; i < initialAccounts.length; i++) {
    const record = initialAccounts[i];

    if (typeof record !== 'object' || record === null) {
      throw new Error('Each account must be an object');
    }

    const id = record.id;
    const balance = record.balance;

    if (typeof id !== 'string') {
      throw new Error('Account id must be a string');
    }

    if (!Number.isInteger(balance) || balance < 0 || balance > Number.MAX_SAFE_INTEGER) {
      throw new Error('Account balance must be a nonnegative safe integer');
    }

    if (accounts.has(id)) {
      throw new Error('Duplicate account id');
    }

    accounts.set(id, balance);
    accountOrder.push(id);
  }

  // Return ledger object with snapshot and apply methods
  return {
    snapshot() {
      return accountOrder.map(id => ({
        id,
        balance: accounts.get(id)
      }));
    },

    apply(batch) {
      if (!Array.isArray(batch)) {
        throw new Error('batch must be an array');
      }

      // First pass: validate transfer structure and account existence
      const operations = [];

      for (let i = 0; i < batch.length; i++) {
        const transfer = batch[i];

        if (typeof transfer !== 'object' || transfer === null) {
          throw new Error('Each transfer must be an object');
        }

        const from = transfer.from;
        const to = transfer.to;
        const amount = transfer.amount;

        if (typeof from !== 'string') {
          throw new Error('Transfer from must be a string');
        }

        if (typeof to !== 'string') {
          throw new Error('Transfer to must be a string');
        }

        if (!Number.isInteger(amount) || amount <= 0 || amount > Number.MAX_SAFE_INTEGER) {
          throw new Error('Transfer amount must be a positive safe integer');
        }

        if (!accounts.has(from)) {
          throw new Error(`Source account "${from}" does not exist`);
        }

        if (!accounts.has(to)) {
          throw new Error(`Destination account "${to}" does not exist`);
        }

        operations.push({ from, to, amount });
      }

      // Second pass: simulate all transfers to validate funds and safe integer limits
      const tempBalances = new Map(accounts);

      for (const op of operations) {
        const fromBalance = tempBalances.get(op.from);

