export async function retry(operation, options) {
  // Validate arguments BEFORE handling cancellation
  if (typeof operation !== 'function') {
    throw new TypeError('operation must be a function');
  }

  if (options === null || typeof options !== 'object' || Array.isArray(options)) {
    throw new TypeError('options must be a non-null object');
  }

  const { maxAttempts, shouldRetry, wait, signal } = options;

  if (!Number.isSafeInteger(maxAttempts) || maxAttempts <= 0) {
    throw new TypeError('maxAttempts must be a positive safe integer');
  }

  if (typeof shouldRetry !== 'function') {
    throw new TypeError('shouldRetry must be a function');
  }

  if (typeof wait !== 'function') {
    throw new TypeError('wait must be a function');
  }

  // Validate signal if provided
  if (signal !== undefined && !(signal instanceof AbortSignal)) {
    throw new TypeError('signal must be an AbortSignal');
  }

  // Check if already aborted
  if (signal?.aborted) {
    throw signal.reason;
  }

  // Track terminal state
  let terminalCause = null;
  let hasTerminal = false;

  // Set up abort listener
  const abortHandler = () => {
    if (!hasTerminal) {
      terminalCause = signal.reason;
      hasTerminal = true;
    }
  };

  if (signal) {
    signal.addEventListener('abort', abortHandler);
  }

  try {
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      // Check for abort before attempting
      if (hasTerminal) {
        throw terminalCause;
      }

      let operationResult;
      try {
        operationResult = await operation(attempt, signal);
      } catch (failure) {
        // Operation failed

        // Check for abort after operation
        if (hasTerminal) {
          throw terminalCause;
        }

        // If this was the last attempt, fail with the operation failure
        if (attempt === maxAttempts) {
          throw failure;
        }

        // Call shouldRetry policy (synchronous)
        let shouldContinue;
        try {
          shouldContinue = shouldRetry(failure, attempt);
        } catch (policyError) {
          // Policy threw - this is terminal
          if (!hasTerminal) {
            terminalCause = policyError;
            hasTerminal = true;
          }
          throw terminalCause;
        }

        // Check for abort after policy call
        if (hasTerminal) {
          throw terminalCause;
        }

        // Handle thenable returns from shouldRetry
        if (shouldContinue && typeof shouldContinue === 'object' && typeof shouldContinue.then === 'function') {
          try {
            shouldContinue = await shouldContinue;
          } catch (thenableError) {
            // Thenable rejected - this is terminal
            if (!hasTerminal) {
              terminalCause = thenableError;
              hasTerminal = true;
            }
            throw terminalCause;
          }
        }

        // Check for abort after policy thenable
        if (hasTerminal) {
          throw terminalCause;
        }

        // Validate return type is boolean
        if (typeof shouldContinue !== 'boolean') {
          const typeError = new TypeError('shouldRetry must return a boolean');
          if (!hasTerminal) {
            terminalCause = typeError;
            hasTerminal = true;
          }
          throw terminalCause;
        }

        // If policy says don't retry - this is terminal
        if (!shouldContinue) {
          throw failure;
        }

        // Check for abort after policy result
        if (hasTerminal) {
          throw terminalCause;
        }

        // Call wait hook
        try {
          const waitResult = wait(attempt, signal);
          if (waitResult && typeof waitResult === 'object' && typeof waitResult.then === 'function') {
            await waitResult;
          }
        } catch (waitError) {
          // Wait failed - this is terminal
          if (!hasTerminal) {
            terminalCause = waitError;
            hasTerminal = true;
          }
          throw terminalCause;
        }

        // Check for abort after wait
        if (hasTerminal) {
          throw terminalCause;
        }

        // Continue to next attempt
        continue;
      }

      // Operation succeeded
      return operationResult;
    }
  } finally {
    if (signal) {
      signal.removeEventListener('abort', abortHandler);
    }
  }
}

