      throw new Error('Balance must be a non-negative safe integer');
    }

    const accountRecord = { id, balance };
    accounts.push(accountRecord);
    accountMap.set(id, accountRecord);
    seenIds.add(id);
  }

  function snapshot() {
    return accounts.map(record => ({ id: record.id, balance: record.balance }));
  }

