  if (!Array.isArray(initialAccounts)) {
    throw new Error('initialAccounts must be an array');
  }

  const accounts = [];
  const accountMap = new Map();

  for (let i = 0; i < initialAccounts.length; i++) {
    const record = initialAccounts[i];

    if (!record || typeof record !== 'object' || Array.isArray(record)) {
      throw new Error('Invalid account record');
    }

    const { id, balance } = record;

    if (typeof id !== 'string') {
      throw new Error('Invalid account id');
    }

    if (accountMap.has(id)) {
      throw new Error('Duplicate account id');
    }

    if (!Number.isSafeInteger(balance) || balance < 0) {
      throw new Error('Invalid account balance');
    }

    accounts.push({ id, balance });
    accountMap.set(id, i);
  }

