        throw new Error('Invalid transfer record');
      }

      const { from, to, amount } = transfer;

      if (typeof from !== 'string' || !accountMap.has(from)) {
        throw new Error('Invalid or missing source account');
      }

      if (typeof to !== 'string' || !accountMap.has(to)) {
        throw new Error('Invalid or missing destination account');
      }

      if (!Number.isSafeInteger(amount) || amount <= 0) {
        throw new Error('Invalid transfer amount');
