    if (record == null || typeof record !== 'object' || Array.isArray(record)) {
      throw new Error('Each account must be an object');
    }

    const { id, balance } = record;

    if (typeof id !== 'string') {
      throw new Error('Account id must be a string');
    }

    if (!Number.isSafeInteger(balance) || balance < 0) {
      throw new Error('Account balance must be a nonnegative safe integer');
    }

    if (idSet.has(id)) {
      throw new Error('Account ids must be unique');
    }

    idSet.add(id);
    accounts.push({ id, balance });
  }

  return {
    snapshot() {
      return accounts.map(({ id, balance }) => ({ id, balance }));
    },

    apply(batch) {
      if (!Array.isArray(batch)) {
        throw new Error('batch must be an array');
      }

      const transfers = [];
      for (const record of batch) {
        if (record == null || typeof record !== 'object' || Array.isArray(record)) {
          throw new Error('Each transfer must be an object');
        }

        const { from, to, amount } = record;

        if (typeof from !== 'string') {
          throw new Error('Transfer from must be a string');
        }

        if (typeof to !== 'string') {
          throw new Error('Transfer to must be a string');
        }

        if (!Number.isSafeInteger(amount) || amount <= 0) {
          throw new Error('Transfer amount must be a positive safe integer');
        }

