    throw new TypeError('maxAttempts must be a positive safe integer');
  }

  if (typeof operation !== 'function') {
    throw new TypeError('operation must be a function');
  }

  if (typeof shouldRetry !== 'function') {
    throw new TypeError('shouldRetry must be a function');
  }

  if (typeof wait !== 'function') {
    throw new TypeError('wait must be a function');
  }

  // Validate signal if provided
  if (signal !== undefined && signal !== null) {
    if (!(signal instanceof AbortSignal)) {
      throw new TypeError('signal must be an AbortSignal');
    }
  }

  // Check if signal is already aborted
  if (signal?.aborted) {
    throw signal.reason;
  }

  // Track terminal cause and abort listeners
  let terminalCause = null;
  const abortListeners = [];

  try {
    // Set up abort listener if signal provided
    const handleAbort = () => {
      if (terminalCause === null) {
        terminalCause = signal.reason;
      }
    };

    if (signal) {
      signal.addEventListener('abort', handleAbort);
      abortListeners.push({ signal, handler: handleAbort });
    }

    // Retry loop
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      // If we have a terminal cause, reject with it
      if (terminalCause !== null) {
        throw terminalCause;
      }

      // Call operation
      let operationFailure;
      try {
        const result = await operation(attempt, signal);
        return result;
      } catch (failure) {
        operationFailure = failure;
      }

      // Operation failed. Check if abort happened during operation
      if (terminalCause !== null) {
        throw terminalCause;
      }

      // If max attempts reached, this failure is terminal
      if (attempt === maxAttempts) {
        terminalCause = operationFailure;
        throw operationFailure;
      }

      // Call shouldRetry policy
      let shouldRetryResult;
      try {
        shouldRetryResult = shouldRetry(operationFailure, attempt);
      } catch (policyThrow) {
        if (terminalCause === null) {
          terminalCause = policyThrow;
        }
        throw terminalCause;
      }

      // Check if abort happened during shouldRetry call
      if (terminalCause !== null) {
        throw terminalCause;
      }

      // Validate shouldRetry returned a boolean
      if (typeof shouldRetryResult !== 'boolean') {
        // Observe thenables to prevent unhandled rejection
        if (shouldRetryResult != null && typeof shouldRetryResult.then === 'function') {
          shouldRetryResult.then(() => {}, () => {});
        }
        const typeError = new TypeError('shouldRetry must return a boolean');
        terminalCause = typeError;
        throw typeError;
      }

      // If policy says don't retry, this failure is terminal
      if (!shouldRetryResult) {
        terminalCause = operationFailure;
        throw operationFailure;
      }

      // Check if abort happened after policy returned true
      if (terminalCause !== null) {
        throw terminalCause;
      }

      // Call wait
      try {
        await wait(attempt, signal);
      } catch (waitFailure) {
        if (terminalCause === null) {
          terminalCause = waitFailure;
        }
        throw terminalCause;
      }

      // Check if abort happened during wait
      if (terminalCause !== null) {
        throw terminalCause;
      }

      // Loop continues to next attempt
    }
  } finally {
    // Remove all abort listeners
    for (const { signal: sig, handler } of abortListeners) {
      sig.removeEventListener('abort', handler);
    }
  }
}
